import{_ as t,o as s,c as r,a5 as o}from"./chunks/framework.CsGesDJn.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-16-leave-workspace/report3_spec.md","filePath":"feature/agency-workspace/3-4-16-leave-workspace/report3_spec.md"}'),i={name:"feature/agency-workspace/3-4-16-leave-workspace/report3_spec.md"};function a(n,e,l,c,h,p){return s(),r("div",null,[...e[0]||(e[0]=[o("<p><strong>3.4.16 Leave Workspace</strong></p><p><strong>Function Trigger</strong></p><p>Begins when an active member of a Workspace confirms leaving that Workspace.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: Any active member of the Workspace - MANAGER, CREATOR, or CLIENT - acting on their own membership only.</li><li><strong>Purpose</strong>: Lets a member leave a Workspace they no longer take part in while keeping their Agency membership, so they can still join other Workspaces.</li><li><strong>Interface</strong>: &quot;Leave Workspace&quot; action in Workspace settings or the members screen, shown only to the signed-in user themselves, followed by a confirmation dialog.</li><li><strong>Data Processing</strong>: The system locates the caller&#39;s own active membership in the Workspace and marks it inactive, without touching the caller&#39;s Agency membership.</li></ul><p><strong>Screen Layout</strong></p><p>Figure - Leave Workspace Dialog:</p><ul><li>A &quot;Leave Workspace&quot; action inside Workspace settings or the members screen, visible only to the signed-in user.</li><li>A confirmation dialog explaining that the member leaves this Workspace but remains in the Agency.</li><li>A blocked state with a clear message when the member is the last MANAGER of the Workspace.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: the Workspace identifier; the caller&#39;s authenticated identity, taken from the session principal.</li><li><strong>Input optional</strong>: none.</li><li><strong>System data</strong>: the caller&#39;s active membership row in that Workspace; the count of active MANAGERs in the Workspace.</li><li><strong>Output</strong>: confirmation that the membership has been deactivated; no other data is returned.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-29</strong>: The caller identity always comes from the session principal and the action applies only to the caller&#39;s own membership row; no other member can be targeted.</li><li><strong>BR-28 / BR-30</strong>: Leaving is a soft delete (isActive=false); the caller loses access immediately because every scoped query re-checks membership. The caller&#39;s Agency membership is never modified. A MANAGER cannot leave if they are the last active MANAGER of the Workspace - the MANAGER role must be handed over first through FR 3.4.20.</li><li><strong>BR-31</strong>: The Workspace role set assignable at Workspace level is MANAGER, CREATOR, CLIENT (OWNER exists only at Agency level); the last-MANAGER guard applies only when the membership being deactivated carries the MANAGER role.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>The caller must hold an active membership in that Workspace; otherwise 403 WORKSPACE_ACCESS_DENIED, toast <strong>MSG40</strong>.</li><li>The caller must not be the only active MANAGER of the Workspace; otherwise 409 LAST_MANAGER_CANNOT_BE_REMOVED, toast <strong>MSG37</strong>.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ol><li>Member opens Workspace settings or the members screen and chooses &quot;Leave Workspace&quot;.</li><li>Member confirms in the dialog.</li><li>System looks up the caller&#39;s own active membership in the Workspace; if none exists the request fails with 403 WORKSPACE_ACCESS_DENIED.</li><li>System applies the last-MANAGER guard: members who are not MANAGER pass, and a MANAGER passes when another active MANAGER exists.</li><li>System marks the membership inactive.</li><li>The member is taken out of the Workspace back to the Workspace list, while remaining in the Agency and in their other Workspaces; toast <strong>MSG36</strong>.</li></ol></li><li><p><strong>Abnormal Cases</strong></p><ul><li>3.a1: Caller has no active membership in that Workspace -&gt; 403 WORKSPACE_ACCESS_DENIED, toast <strong>MSG40</strong>. 3.a2: The caller returns to the Workspace list; the Workspace they tried to leave does not appear.</li><li>4.a1: Caller is the only active MANAGER of the Workspace -&gt; 409 LAST_MANAGER_CANNOT_BE_REMOVED, toast <strong>MSG37</strong>. 4.a2: Another MANAGER must be assigned first through FR 3.4.20, then the caller retries leaving.</li><li>4.b1: A CREATOR or CLIENT leaves while other members remain -&gt; the request always succeeds. 4.b2: The member is removed from the Workspace and returned to the Workspace list.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>The caller&#39;s membership in the Workspace is inactive and the Workspace no longer appears in their list.</li><li>The caller&#39;s Agency membership is untouched; they remain in the Agency and in their other Workspaces.</li></ul>",14)])])}const u=t(i,[["render",a]]);export{m as __pageData,u as default};
